private static int decodeOctets(int i,ByteBuffer bb,StringBuilder sb){
    if (bb == null || sb == null) {
        return i;
    }
    try {
        if (i >= bb.limit()) {
            return i;
        }
        int b0 = bb.get(i) & 0xFF;
        int codePoint;
        int bytesConsumed;
        if ((b0 & 0x80) == 0) {
            // 1-byte ASCII
            codePoint = b0;
            bytesConsumed = 1;
        } else if ((b0 & 0xE0) == 0xC0) {
            // 2-byte sequence
            if (i + 1 >= bb.limit()) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int b1 = bb.get(i + 1) & 0xFF;
            if ((b1 & 0xC0) != 0x80) {
                sb.append('\uFFFD');
                return i + 1;
            }
            codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
            bytesConsumed = 2;
        } else if ((b0 & 0xF0) == 0xE0) {
            // 3-byte sequence
            if (i + 2 >= bb.limit()) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
                sb.append('\uFFFD');
                return i + 1;
            }
            codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
            bytesConsumed = 3;
        } else if ((b0 & 0xF8) == 0xF0) {
            // 4-byte sequence
            if (i + 3 >= bb.limit()) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            int b3 = bb.get(i + 3) & 0xFF;
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                sb.append('\uFFFD');
                return i + 1;
            }
            codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            bytesConsumed = 4;
        } else {
            // invalid first byte
            sb.append('\uFFFD');
            return i + 1;
        }
        if (codePoint <= 0xFFFF) {
            sb.append((char) codePoint);
        } else {
            codePoint -= 0x10000;
            char high = (char) ((codePoint >> 10) + 0xD800);
            char low = (char) ((codePoint & 0x3FF) + 0xDC00);
            sb.append(high).append(low);
        }
        return i + bytesConsumed;
    } catch (Exception e) {
        return i;
    }
}

