        throw new IllegalArgumentException("size must be non-negative");
    }
    if (data == null) {
        data = new byte[size];
        return;
    }
    int loc0 = 2 * data.length;
    int loc1 = length + size;
    byte[] loc2 = new byte[loc0 > loc1 ? loc0 : loc1];
    System.arraycopy(data, 0, loc2, 0, length);
    data = loc2;
}

