private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) return null;
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) return node;
    // detach leftChild's right subtree and attach to node
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }
    // make node the right child of leftChild
    leftChild.right = node;
    // update parent links
    leftChild.parent = node.parent;
    if (node.parent != null) {
        if (node.parent.left == node) {
            node.parent.left = leftChild;
        } else if (node.parent.right == node) {
            node.parent.right = leftChild;
        }
    }
    node.parent = leftChild;
    return leftChild;
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath vector cannot be null");
    }
    if (dir == null || dir.isEmpty()) {
        throw new IllegalArgumentException("Directory path cannot be null or empty");
    }
    File directory = new File(dir);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a valid directory: " + dir);
    }
    File[] files = directory.listFiles();
    if (files == null) {
        return;
    }
    for (File f : files) {
        if (f.isFile() && f.getName().toLowerCase().endsWith(".jar")) {
            try {
                URL url = f.toURI().toURL();
                cpV.add(url);
            } catch (Exception e) {
                // Wrap and rethrow as unchecked to avoid changing method signature
                throw new RuntimeException("Failed to convert file to URL: " + f, e);
            }
        }
    }
}

