@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) return;
    // Add all vertices from the resultMap to the target graph
    for (V v : resultMap.values()){
        target.addVertex(v);
    }
    // Separate vertices into left and right partitions based on key prefixes
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        if (key != null){
            if (key.startsWith("left")){
                left.add(entry.getValue());
            } else if (key.startsWith("right")){
                right.add(entry.getValue());
            }
        }
    }
    // Connect every left vertex to every right vertex to form a complete bipartite graph
    for (V l : left){
        for (V r : right){
            target.addEdge(l, r);
        }
    }
}

