public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    if (args == null || args.length == 0) {
        return null;
    }

    // Build a map from type variables to actual types based on targetType's hierarchy
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    Class<?> current = targetType;
    while (current != null) {
        // Superclass
        Type genericSuper = current.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType superPT = (ParameterizedType) genericSuper;
            Class<?> raw = (Class<?>) superPT.getRawType();
            TypeVariable<?>[] vars = raw.getTypeParameters();
            Type[] actuals = superPT.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                typeVarMap.put(vars[i], actuals[i]);
            }
        }
        // Interfaces
        for (Type iface : current.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType ifacePT = (ParameterizedType) iface;
                Class<?> raw = (Class<?>) ifacePT.getRawType();
                TypeVariable<?>[] vars = raw.getTypeParameters();
                Type[] actuals = ifacePT.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    typeVarMap.put(vars[i], actuals[i]);
                }
            }
        }
        current = current.getSuperclass();
    }

    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Class<?> resolved = resolveTypeToClass(args[i], typeVarMap);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

private static Class<?> resolveTypeToClass(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        Type raw = ((ParameterizedType) type).getRawType();
        if (raw instanceof Class<?>) {
            return (Class<?>) raw;
        }
    }
    if (type instanceof TypeVariable<?>) {
        TypeVariable<?> tv = (TypeVariable<?>) type;
        Type actual = map.get(tv);
        if (actual == null) {
            return null;
        }
        return resolveTypeToClass(actual, map);
    }
    // WildcardType, GenericArrayType, or other types are not resolvable to a raw class
    return null;
}

