static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index > str.length() || len > str.length() - index) {
        throw new IllegalArgumentException("Invalid index or length");
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            size += utf8ByteCount(codePoint);
            i += 2;
        } else {
            int codePoint = ch;
            size += utf8ByteCount(codePoint);
            i++;
        }
    }
    return size;
}

private static int utf8ByteCount(int codePoint) {
    if (codePoint <= 0x7F) {
        return 1;
    } else if (codePoint <= 0x7FF) {
        return 2;
    } else if (codePoint <= 0xFFFF) {
        return 3;
    } else {
        return 4;
    }
}

