public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }
    int start = desiredCapacity;
    int limit;
    if (desiredCapacity >= 1000) {
        long limitLong = (long) desiredCapacity * 111L / 100L;
        limit = (limitLong > Integer.MAX_VALUE) ? Integer.MAX_VALUE : (int) limitLong;
    } else {
        limit = desiredCapacity;
    }
    for (int n = start; n <= limit; n++) {
        if (isPrime(n)) {
            return n;
        }
    }
    for (int n = limit + 1; n > 0; n++) {
        if (isPrime(n)) {
            return n;
        }
        if (n == Integer.MAX_VALUE) {
            break;
        }
    }
    throw new RuntimeException("No prime found");
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if ((n & 1) == 0) return false;
    int sqrt = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrt; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

