private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject json = new JsonObject();
    if (properties == null) {
        return json;
    }
    for (KeyStringValuePair pair : properties) {
        if (pair == null) {
            continue;
        }
        String key = pair.getKey();
        if (key == null) {
            continue;
        }
        Object value = pair.getValue();
        if (value == null) {
            json.add(key, JsonNull.INSTANCE);
        } else if (value instanceof Number) {
            json.addProperty(key, (Number) value);
        } else if (value instanceof Boolean) {
            json.addProperty(key, (Boolean) value);
        } else if (value instanceof String) {
            json.addProperty(key, (String) value);
        } else {
            json.addProperty(key, value.toString());
        }
    }
    return json;
}

protected int removeUnusedNodes(){
    int removed = 0;
    try {
        if (root == null) {
            return 0;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            java.util.List<Category> children = new java.util.ArrayList<>(current.getChildren());
            for (Category child : children) {
                if (!child.isActive()) {
                    current.removeChild(child);
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        System.err.println("Error removing unused nodes: " + e.getMessage());
    }
    return removed;
}

protected Label readLabel(final int bytecodeOffset, final Label[] labels) {
