final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        int offset = constantPoolOffsets[constantPoolEntryIndex];
        if (offset <= 0) {
            throw new IllegalArgumentException("Invalid constant pool index");
        }
        byte tag = classFileBuffer[offset];
        if (tag != 1) { // CONSTANT_Utf8 tag
            throw new IllegalArgumentException("Constant pool entry is not a UTF-8");
        }
        int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
        if (length > charBuffer.length) {
            throw new IllegalArgumentException("charBuffer too small for UTF-8 string");
        }
        String s = new String(classFileBuffer, offset + 3, length, StandardCharsets.UTF_8);
        s.getChars(0, length, charBuffer, 0);
        return s;
    } catch (Exception e) {
        throw new RuntimeException("Failed to read UTF-8 constant pool entry", e);
    }
}

private static char decodeHexNibble(final char c) {
    if ('0' <= c && c <= '9') {
        return (char) (c - '0');
    } else if ('a' <= c && c <= 'f') {
        return (char) (c - 'a' + 10);
    } else if ('A' <= c && c <= 'F') {
        return (char) (c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (Long.MAX_VALUE / result < i) {
            throw new ArithmeticException("long overflow");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }
    // If the start node is the stop node, return a circulator positioned at stop
    if (start == stop) {
        return new OuterFaceCirculator(stop, dir);
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Traverse the outer face until we hit the stop node or find a node satisfying the predicate
    while (true) {
        Node current = circ.getNode(); // assume OuterFaceCirculator exposes the current node
        if (current == stop) {
            return circ;
        }
        if (predicate.test(current)) {
            return circ;
        }
        circ.next(); // advance to the next node in the specified direction
        // If we loop back to the start without finding the stop node, break to avoid infinite loop
        if (circ.getNode() == start) {
            return new OuterFaceCirculator(stop, dir);
        }
    }
}

