public double vertexWeight(Set<V> v) {
    double sum = 0.0;
    if (v == null) {
        return sum;
    }
    try {
        for (V vertex : v) {
            if (vertex == null) {
                continue;
            }
            // Assuming a method getIncomingEdges that returns a collection of edges
            Collection<Edge<V>> incoming = getIncomingEdges(vertex);
            if (incoming != null) {
                for (Edge<V> e : incoming) {
                    if (e != null) {
                        sum += e.weight();
                    }
                }
            }
        }
    } catch (Exception e) {
        // In case of any runtime issue, return the sum computed so far
    }
    return sum;
}

public int compare(Object aObj1,Object aObj2){
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable && aObj1.getClass() == aObj2.getClass()) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("Objects are not mutually comparable", e);
        }
    }
    throw new IllegalArgumentException("Objects are not comparable");
}

