protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    java.util.List<E> remaining = new java.util.ArrayList<E>(tour);
    java.util.List<E> used = new java.util.ArrayList<E>();
    java.util.List<V> vertices = new java.util.ArrayList<V>();
    // start from the source of the first edge
    E first = remaining.get(0);
    V start = graph.getEdgeSource(first);
    vertices.add(start);
    V current = start;
    while (!remaining.isEmpty()) {
        boolean found = false;
        java.util.Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                vertices.add(tgt);
                current = tgt;
                used.add(e);
                it.remove();
                found = true;
                break;
            } else if (tgt.equals(current)) {
                vertices.add(src);
                current = src;
                used.add(e);
                it.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Edges do not form a continuous path");
        }
    }
    double weight = 0.0;
    for (E e : used) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.traverse.GraphPathImpl<V,E>(graph, vertices.get(0), vertices.get(vertices.size() - 1), used, weight);
}

