int addConstantNameAndType(final String name, final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    // Search for an existing CONSTANT_NameAndType_info
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int nameIdx = readValue(i);
            int descIdx = readValue(i + 1);
            if (nameIdx >= 0 && descIdx >= 0 && nameIdx < utf8s.length && descIdx < utf8s.length) {
                if (name.equals(utf8s[nameIdx]) && descriptor.equals(utf8s[descIdx])) {
                    return i;
                }
            }
        }
    }
    // Add new UTF8 constants for name and descriptor
    int nameIdx = addConstantUtf8(name);
    int descIdx = addConstantUtf8(descriptor);
    // Ensure capacity for two new entries
    if (maxPoolSize + 2 > types.length) {
        int newSize = Math.max(types.length * 2, maxPoolSize + 2);
        byte[] newTypes = new byte[newSize];
        System.arraycopy(types, 0, newTypes, 0, types.length);
        types = newTypes;
        int[] newOffsets = new int[newSize];
        System.arraycopy(offsets, 0, newOffsets, 0, offsets.length);
        offsets = newOffsets;
    }
    // Append the new CONSTANT_NameAndType_info
    int index = maxPoolSize;
    types[index] = NAME_TYPE;
    offsets[index] = nameIdx;
    offsets[index + 1] = descIdx;
    maxPoolSize += 2;
    return index;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            if (next == 'u' && i + 5 < len) {
                String hex = input.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    sb.append('\\').append('u').append(hex);
                }
                i += 5;
            } else {
                sb.append(next);
                i++;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

