private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    try{
        if(bounds == null || bounds.isEmpty()){
            return new Pair<>(new ArrayList<>(), 0L);
        }
        int n = bounds.size();
        List<Integer> suffix = new ArrayList<>(n);
        // initialize list with zeros
        for(int i = 0; i < n; i++){
            suffix.add(0);
        }
        long running = 0;
        for(int i = n - 1; i >= 0; i--){
            Integer valObj = bounds.get(i);
            int val = (valObj == null) ? 0 : valObj;
            running += val;
            suffix.set(i, (int)running);
        }
        return new Pair<>(suffix, running);
    }catch(Exception e){
        return new Pair<>(new ArrayList<>(), 0L);
    }
}

public static final <V> void reverse(V[] arr,int from,int to){
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        throw new IllegalArgumentException("list cannot be null");
    }
    if (list == this) {
        return;
    }
    // Acquire locks in a consistent order to avoid deadlock
    Object firstLock = System.identityHashCode(this) < System.identityHashCode(list) ? this : list;
    Object secondLock = firstLock == this ? list : this;
    synchronized(firstLock) {
        synchronized(secondLock) {
            ListNode<E> current = list.head;
            while (current != null) {
                ListNode<E> next = current.next;
                list.removeListNode(current);
                this.addListNode(current);
                current = next;
            }
        }
    }
}

