private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    if (vertices.size() <= 1) {
        return true;
    }
    try {
        for (V v1 : vertices) {
            for (V v2 : vertices) {
                if (!v1.equals(v2)) {
                    if (graph.getEdge(v1, v2) == null) {
                        return false;
                    }
                }
            }
        }
        return true;
    } catch (Exception e) {
        return false;
    }
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) return bounds;
    try{
        for (K key : keys){
            Integer maxLower = Integer.MIN_VALUE;
            if (key instanceof Integer){
                int k = (Integer) key;
                for (K other : keys){
                    if (other instanceof Integer){
                        int o = (Integer) other;
                        if (o < k && o > maxLower){
                            maxLower = o;
                        }
                    }
                }
                bounds.add(maxLower);
            } else {
                bounds.add(null);
            }
        }
    } catch (Exception e){
        // In case of unexpected runtime issues, return what has been computed so far
    }
    return bounds;
}

private void pop(final String descriptor) {
    int i = 0;
    int len = descriptor.length();
    // Handle method descriptor: pop argument types
    if (len > 0 && descriptor.charAt(0) == '(') {
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            // Skip the type descriptor
            char c = descriptor.charAt(i);
            // Skip array brackets
            while (c == '[') {
                i++;
                if (i >= len) break;
                c = descriptor.charAt(i);
            }
            if (c == 'L') {
                // Object type: skip until ';'
                i = descriptor.indexOf(';', i);
                if (i == -1) break; // malformed descriptor
                i++; // move past ';'
            } else {
                // Primitive type: single char
                i++;
            }
            // Pop one slot from the stack
            pos--;
        }
        // Skip ')'
        i++;
    } else {
        // Single type descriptor
        char c = descriptor.charAt(i);
        // Skip array brackets
        while (c == '[') {
            i++;
            if (i >= len) break;
            c = descriptor.charAt(i);
        }
        if (c == 'L') {
            // Object type: skip until ';'
            i = descriptor.indexOf(';', i);
            if (i != -1) i++; // move past ';'
        } else {
            // Primitive type: single char
            i++;
        }
        // Pop one slot from the stack
        pos--;
    }
}

private List<Integer> computeUpperBounds(List<K> keys){
