public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // If the relative path is actually absolute, just return it
    if (relativePath.startsWith("/")) {
        return relativePath;
    }
    // Determine if the original path is absolute
    boolean leadingSlash = path.startsWith("/");
    // Split the base path into components, ignoring empty parts and "."
    String[] baseParts = path.split("/");
    Deque<String> stack = new ArrayDeque<>();
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        stack.addLast(part);
    }
    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }
    // If the result is empty and the original path was absolute, return "/"
    if (result.length() == 0 && leadingSlash) {
        return "/";
    }
    return result.toString();
}

